def expansion():
    result = []
    for category, block in ROWS.items():
        offset = 10 if category not in CATEGORIES else 0
        for index, line in enumerate(block.strip().splitlines(), offset + 1):
            difficulty, prompt, answer, alternatives, explanation, source, image = line.split('|')
            result.append(dict(id=f'seed-{category}-{index:02d}', category=category,
                               difficulty=difficulty, prompt=prompt, answer=answer,
                               alternatives=alternatives.split(';'), explanation=explanation,
                               source_url=source if source.startswith('https://') else
                               'https://en.wikipedia.org/wiki/' + quote(source.replace(' ', '_')),
                               image_key=image or None))
    return result
